insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-201","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen combined with a non-metal is assigned the oxidation number","options":["$+1$","$-1$","$0$","$+2$"],"answer_index":0,"explanation":"In hydrides of non-metals (HCl, H$_2$O, NH$_3$) hydrogen is $+1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-202","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In their compounds the alkali metals (Li, Na, K, …) show the oxidation number","options":["$0$","$+1$","$+2$","$-1$"],"answer_index":1,"explanation":"Group 1 metals lose one valence electron and are $+1$ in compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-203","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Fluorine, being the most electronegative element, has in all its compounds the oxidation number","options":["$0$","$+1$","$-1$","$+2$"],"answer_index":2,"explanation":"Fluorine is always $-1$ in compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-204","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In hydrogen chloride the oxidation number of chlorine is","options":["$+1$","$-1$","$0$","$+7$"],"answer_index":1,"explanation":"H is $+1$ and the molecule is neutral, so Cl is $-1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-205","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Sulphur in hydrogen sulphide $\\mathrm{H_2S}$ has the oxidation number","options":["$+2$","$-2$","$+6$","$0$"],"answer_index":1,"explanation":"Two hydrogens at $+1$ force sulphur to $-2$ in the neutral molecule.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-206","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Nitrogen in ammonia $\\mathrm{NH_3}$ is assigned the oxidation number","options":["$+3$","$-3$","$+5$","$0$"],"answer_index":1,"explanation":"Three hydrogens at $+1$ give nitrogen $-3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-207","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Carbon in methane $\\mathrm{CH_4}$ carries the oxidation number","options":["$+4$","$-4$","$0$","$+2$"],"answer_index":1,"explanation":"Four hydrogens at $+1$ leave carbon at $-4$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-208","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In hydrogen peroxide $\\mathrm{H_2O_2}$ the oxidation number of each oxygen atom is","options":["$-2$","$-1$","$0$","$+1$"],"answer_index":1,"explanation":"Peroxidic oxygen is $-1$; two H at $+1$ and two O at $-1$ balance the molecule.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-209","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Sulphur in sulphuric acid $\\mathrm{H_2SO_4}$ has the oxidation number","options":["$+2$","$+4$","$+6$","$-2$"],"answer_index":2,"explanation":"$2(+1) + \\mathrm{S} + 4(-2) = 0$ gives S $= +6$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-210","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Chromium in potassium dichromate $\\mathrm{K_2Cr_2O_7}$ has the oxidation number","options":["$+3$","$+6$","$+7$","$+2$"],"answer_index":1,"explanation":"$2(+1) + 2\\mathrm{Cr} + 7(-2) = 0$ gives each Cr $= +6$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
